-- width of a text at scale 1 (a button tag <...> counts as two characters, a CJK glyph as two)
local function text_width(s)
  local units, i, n = 0, 1, string.len(s)
  while i <= n do
    local b = string.byte(s, i)
    if b == 60 then   -- "<"
      local close = string.find(s, ">", i, true)
      if close ~= nil then
        units = units + 2
        i = close + 1
      else
        units = units + 1
        i = i + 1
      end
    else
      local len = b >= 0xF0 and 4 or (b >= 0xE0 and 3 or (b >= 0xC0 and 2 or 1))
      units = units + (len >= 3 and 2 or 1)
      i = i + len
    end
  end
  return math.max(units, 1) * P.LABEL.CHAR_WIDTH
end

-- Returns a slot's position from the pitch's centre (pitch pixels, y up).
function P.slot_offset(formation, slot)
  local G, R = P.PITCH, P.FORMATION
  local ok, x, _, y = VRFW.host.command(P.C.FORMATION_INFO, 4, formation, slot, R.BASE_SET)
  if ok ~= true then
    x, y = 0, 0
  end
  x, y = x or 0, y or 0
  local total = math.abs(G.TOP_Y - G.BOTTOM_Y)
  local above = math.abs(G.CENTRE_Y - G.TOP_Y)
  local below = math.abs(G.CENTRE_Y - G.BOTTOM_Y)
  local depth = y / R.DEPTH_UNITS
  local height_here = -y * (total / R.DEPTH_UNITS) + total * 0.5
  local width_here = (G.TOP_WIDTH - G.BOTTOM_WIDTH) * (height_here / total) + G.BOTTOM_WIDTH
  local px = x * (width_here / R.WIDTH_UNITS)
  local py = below - y * (G.BOTTOM_WIDTH / R.WIDTH_UNITS)
  if depth < 0 then
    py = py + total * depth * above / below
  elseif depth > 0 then
    py = py + above * depth * below / (total * 0.5)
  end
  local okO, dx, dy = VRFW.host.command(P.C.FORMATION_INFO, 4, formation, slot, R.OFFSET_SET)
  if okO == true then
    px = px + (dx or 0) * R.OFFSET_SCALE
    py = py + (dy or 0) * R.OFFSET_SCALE
  end
  py = py - below
  local okK, kind = VRFW.host.command(P.C.FORMATION_INFO, 5, formation, slot)
  if okK == true and kind == 0 then
    py = py + R.KEEPER_LIFT
  end
  return px, py
end

local function formation_name(formation)
  local ok, text = VRFW.host.command(P.C.FORMATION_INFO, 7, formation)
  if ok == true and text ~= nil then
    local name = VRFW.host.command(P.C.TEXT_OF_ID, text)
    return type(name) == "string" and name or ""
  end
  return ""
end

-- Reads the user's active team.
function P.read_dock_team()
  local set = VRFW.host.command(P.C.TEAM_SET)
  if type(set) ~= "number" then
    return nil
  end
  local okF, formation = VRFW.host.command(P.C.TEAM_SET_INFO, set, 0, 4)
  if okF ~= true or type(formation) ~= "number" or formation == 0 then
    return nil
  end
  local okU, uniform = VRFW.host.command(P.C.TEAM_SET_INFO, set, 0, 7)
  local team = {key = "dock:" .. set, formation = formation, name = formation_name(formation), starters = {}}
  for i = 0, P.MEMBER_SLOTS - 1 do
    local okH, handle = VRFW.host.command(P.C.TEAM_MEMBER, set, 0, i, 0)
    local okS, slot = VRFW.host.command(P.C.TEAM_MEMBER, set, 0, i, 1)
    if okH == true and okS == true and type(handle) == "number" and handle ~= 0 and type(slot) == "number"
        and slot >= 0 and slot < P.STARTERS then
      local okP, position = VRFW.host.command(P.C.FORMATION_INFO, 6, formation, slot)
      local okC, captain = VRFW.host.command(P.C.TEAM_SET_INFO, set, 0, 8, handle)
      local level = VRFW.host.command(P.C.CHARA_INFO, handle, 0)
      position = okP == true and position or 0
      team.starters[slot] = {handle = handle, position = position, fill = {
        layerName = P.LAYER.CARD, layerIdx = slot, charaStHdl = handle, isBigCardType = true,
        isForceLeader = false, overwritePosType = position, charaFaceType = 0,
        level = type(level) == "number" and level or 0, isCaptain = okC == true and captain == true,
        uniformId = okU == true and uniform or 0, isMainMember = true, titleAttr = 0, isForceUpdateBustup = false,
        isManager = false, isGrayout = false, isDisableTeamUniform = false, rarityFrameEffectDrawType = 0,
        isTeamDockIconVisible = false, isForcePlayerUniform = true, teamSet = set, faceIconChrStHdl = 0,
        isUpdateTempAvatar = true,
      }}
    end
  end
  return team
end

function P.read_chronicle_team(game, difficulty)
  local okT, id = VRFW.host.command(P.C.CHRONICLE_TEAM, game, 8)
  if okT ~= true or type(id) ~= "number" or id == 0 then
    return nil
  end
  local okF, formation = VRFW.host.command(P.C.TEAM_PARAM, id, 3)
  if okF ~= true or type(formation) ~= "number" or formation == 0 then
    return nil
  end
  local okN, count = VRFW.host.command(P.C.TEAM_PARAM, id, 8)
  local okU, uniform = VRFW.host.command(P.C.TEAM_PARAM, id, 4)
  local team = {key = "chronicle:" .. id, formation = formation, name = formation_name(formation), starters = {}}
  if okN ~= true or type(count) ~= "number" or GetTeamMemberInfo == nil then
    return team
  end
  for i = 0, count - 1 do
    local ok, chara, slot, level, captain, kit = GetTeamMemberInfo(id, i, game, difficulty, true)
    if ok and type(slot) == "number" and slot >= 0 and slot < P.STARTERS then
      local okP, position = VRFW.host.command(P.C.FORMATION_INFO, 6, formation, slot)
      team.starters[slot] = {chara = chara, position = okP == true and position or 0, level = level,
        captain = captain, kit = kit, uniform = okU == true and uniform or 0}
    end
  end
  return team
end

-- the team of the focused row's battle
function P.read_focused_team()
  local L = VRFW.route_board_commands.L
  local rows = L.t3
  local index = VRFW.host.menu_command(P.C.FOCUS_GET, P.ROWS)
  local row = type(rows) == "table" and type(index) == "number" and rows[index + 1] or nil
  if row ~= nil and row.difficultyType == P.CHRONICLE_DIFFICULTY and P.kind == 0 then
    local team = P.read_chronicle_team(L.n4, P.CHRONICLE_DIFFICULTY)
    if team ~= nil then
      return team
    end
    log("no Chronicle team for game", L.n4, "- the active team is shown")
  end
  local team = P.read_dock_team()
  if team ~= nil and row ~= nil then
    P.mark_offenders(team, L.n4, row.difficultyType or 0)
  end
  return team
end

function P.mark_offenders(team, game, difficulty)
  if VRFW.match_challenge == nil or difficulty <= 0 or type(game) ~= "number" then
    return
  end
  local i = VRFW.match_challenge.applies(game, difficulty)
  if i == nil then
    return
  end
  local called, _, _, offenders, players = pcall(VRFW.match_challenge.check, i, 0, VRFW.match_challenge.won(game, difficulty))
  if not called or type(offenders) ~= "table" or type(players) ~= "table" then
    return
  end
  local bad, count = {}, 0
  for _, k in ipairs(offenders) do
    local player = players[k]
    if player ~= nil then
      bad[player.hdl] = true
    end
  end
  for _, card in pairs(team.starters) do
    if card.handle ~= nil and bad[card.handle] then
      card.offender = true
      count = count + 1
    end
  end
  team.key = team.key .. ":challenge" .. i .. ":" .. count
end

local function place(layer, k)
  local b = P.base[layer .. ":" .. k]
  if b == nil then
    return
  end
  local dx, dy = 0, 0
  if (VRFW.route_board_commands ~= nil and VRFW.route_board_commands.panel_shift ~= nil) then
    dx, dy = VRFW.route_board_commands.panel_shift()
  end
  VRFW.host.menu_command(P.C.POS, layer, b[1] + dx, b[2] + dy, 0, k)
end

local function open(layer, k, priority)
  local key = layer .. ":" .. k
  if not P.opened[key] then
    P.opened[key] = true
    VRFW.host.menu_command(P.C.OPEN, layer, k)
  end
  VRFW.host.menu_command(P.C.DRAW_PRIORITY, layer, k, priority, true)
end

-- Draws a card from its own sprites.
local function sprite_card(slot, card)
  local L, S = P.LAYER.CARD, P.SPRITE_CARD
  for _, node in ipairs(S.NODES_OFF) do
    VRFW.host.menu_command(P.C.NODE_VISIBLE, L, node, false, slot)
  end
  for _, mesh in ipairs(S.MESHES_OFF) do
    VRFW.host.menu_command(P.C.MESH_VISIBLE, L, mesh, false, slot)
  end
  local plate = S.PLATE_SLOT
  for _, entry in ipairs(S.PLATES) do
    if math.floor((card.position or 0) / entry[1]) % 2 == 1 then
      plate = entry[2]
      break
    end
  end
  VRFW.host.menu_command(P.C.SPRITE, L, S.TEXTURE, plate, S.PLATE_SLOT, 0, slot)
  VRFW.host.menu_command(P.C.MESH_VISIBLE, L, S.PLATE, true, slot)
  VRFW.face_icon.forget(L, slot)
  if card.handle ~= nil then
    -- a team dock player is drawn from his handle
    VRFW.face_icon.face(L, slot, {handle = card.handle}, S.FACE, S.FACE_SLOT, {kit = 0, keeper = false})
  else
    local chara = VRFW.host.command(P.C.CHARA_OF_PARAM, card.chara)
    if type(chara) ~= "number" or chara == 0 then
      chara = card.chara
    end
    VRFW.face_icon.face(L, slot, chara, S.FACE, S.FACE_SLOT, {kit = 0, keeper = false, use_args = true})
  end
end

-- Fills one card.
local function fill_card(slot)
  local card = P.cards[slot]
  if card == nil then
    VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.CARD, slot, false)
    return
  end
  VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.CARD, slot, true)
  name_card(slot)
  pcall(SetDisableForceCharaInvalidUseTarget)
  local filled
  if card.handle ~= nil then
    filled = VRFW.host.menu_command(P.C.FILL_CARD, card.fill)
  else
    filled = VRFW.host.menu_command(P.C.FILL_MEMBER_CARD, P.LAYER.CARD, slot, card.chara, true, false, card.position, 0, card.level,
      card.captain, false, card.kit, card.uniform)
  end
  if filled == false then
    sprite_card(slot, card)
  end
  pcall(SetEnableForceCharaInvalidUseTarget)
  local logged = P.source .. ":" .. slot
  if not P.logged[logged] then
    P.logged[logged] = true
    log("slot", slot, card.handle ~= nil and "dock" or "chronicle", "fill", tostring(filled), "position", card.position)
  end
  for _, mesh in ipairs(P.CARD_HIDE) do
    VRFW.host.menu_command(P.C.MESH_VISIBLE, P.LAYER.CARD, mesh, false, slot)
  end
  VRFW.host.menu_command(P.C.SCALE, P.LAYER.CARD, P.LAYOUT.CARD_SCALE, P.LAYOUT.CARD_SCALE, 1, slot)
  place(P.LAYER.CARD, slot)
  VRFW.host.menu_command(P.C.DRAW_PRIORITY, P.LAYER.CARD, slot, P.LAYOUT.PRIORITY_CARD, true)
  VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.CARD, slot, true)
  P.mark(slot, card.offender == true)
end

function P.mark(slot, on)
  if instances(P.LAYER.MARK) <= slot then
    return
  end
  if not on then
    if P.opened[P.LAYER.MARK .. ":" .. slot] then
      VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.MARK, slot, false)
    end
    return
  end
  local A = P.LAYOUT
  local b = P.base[P.LAYER.CARD .. ":" .. slot]
  if b == nil then
    return
  end
  open(P.LAYER.MARK, slot, A.PRIORITY_MARK)
  VRFW.host.menu_command(P.C.SCALE, P.LAYER.MARK, A.MARK_SCALE, A.MARK_SCALE, 1, slot)
  P.base[P.LAYER.MARK .. ":" .. slot] = {b[1] + A.MARK_X * A.CARD_SCALE, b[2] + A.MARK_Y * A.CARD_SCALE}
  place(P.LAYER.MARK, slot)
  VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.MARK, slot, true)
end

-- Draws a text line.
local function text_line(k, s, scale, cx, cy, plate)
  local L = P.LABEL
  open(P.LAYER.TEXT, k, P.LAYOUT.PRIORITY_TEXT)
  VRFW.host.menu_command(P.C.MESH_VISIBLE, P.LAYER.TEXT, L.PLATE, plate == true, k)
  VRFW.host.menu_command(P.C.MESH_VISIBLE, P.LAYER.TEXT, L.PLATE_ADD, false, k)
  if not plate then
    VRFW.host.menu_command(P.C.NODE_SCALE, P.LAYER.TEXT, k, L.TEXT_NODE, L.TEXT_BOX_WIDTH, L.TEXT_BOX_HEIGHT)
  end
  VRFW.host.menu_command(P.C.SCALE, P.LAYER.TEXT, 1, 1, 1, k)
  VRFW.host.menu_command(P.C.TEXT, P.LAYER.TEXT, L.TEXT_NODE, s, k)
  VRFW.host.menu_command(P.C.SCALE, P.LAYER.TEXT, scale, scale, 1, k)
  local x
  if plate then
    x = cx - (L.PLATE_LEFT + L.PLATE_WIDTH / 2) * scale   -- the plate centred, the text at its left as retail
  else
    local width = VRFW.host.menu_command(P.C.TEXT_SIZE, P.LAYER.TEXT, k, L.TEXT_NODE)   -- the game's measure (scale 1)
    if type(width) ~= "number" or width <= 0 then
      width = text_width(s)
    end
    x = cx - width * scale / 2 - L.TEXT_LEFT * scale
  end
  P.base[P.LAYER.TEXT .. ":" .. k] = {x, -cy - L.TEXT_MID_Y * scale}
  place(P.LAYER.TEXT, k)
  VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.TEXT, k, s ~= "")
end

function P.hide()
  if not P.shown then
    return
  end
  P.shown = false
  VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.PITCH, 0, false)
  for slot = 0, P.STARTERS - 1 do
    VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.CARD, slot, false)
  end
  VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.TEXT, P.TEXT_FORMATION, false)
  VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.TEXT, P.TEXT_BUTTON, false)
  for slot = 0, P.STARTERS - 1 do
    P.mark(slot, false)
  end
end

function P.draw()
  local team = (VRFW.route_board_commands ~= nil and VRFW.route_board_commands.panel_band_top ~= nil) and P.read_focused_team() or nil
  if team == nil then
    P.source = nil
    return P.hide()
  end
  P.source = team.key
  local count = 0
  for _ in pairs(team.starters) do
    count = count + 1
  end
  log("draw", team.key, "formation", team.formation, team.name, "starters", count)
  local A, G = P.LAYOUT, P.PITCH
  local top = VRFW.route_board_commands.panel_band_top(P.BAND_ID)
  local cx = VRFW.route_board_commands.GEOMETRY.PANEL_MID_X
  -- the formation name
  text_line(P.TEXT_FORMATION, team.name, A.NAME_SCALE, cx, top + A.TOP_GAP + A.NAME_HEIGHT / 2, false)
  -- Computes the pitch layout.
  local pitch_top = top + A.TOP_GAP + A.NAME_HEIGHT + A.NAME_GAP
  local sx, sy = A.PITCH_SCALE_X, A.PITCH_SCALE_Y
  local cy = pitch_top + (G.FIELD_TOP_Y - G.CENTRE_Y) * sy
  open(P.LAYER.PITCH, 0, A.PRIORITY_PITCH)
  VRFW.host.menu_command(P.C.SCALE, P.LAYER.PITCH, sx, sy, 1, 0)
  P.base[P.LAYER.PITCH .. ":0"] = {cx - G.CENTRE_X * sx, -cy - G.CENTRE_Y * sy}
  place(P.LAYER.PITCH, 0)
  VRFW.host.menu_command(P.C.VISIBLE, P.LAYER.PITCH, 0, true)
  -- the starters
  P.cards = team.starters
  for slot = 0, P.STARTERS - 1 do
    local rx, ry = P.slot_offset(team.formation, slot)
    P.base[P.LAYER.CARD .. ":" .. slot] = {cx + rx * sx, -cy + ry * sy}
    open(P.LAYER.CARD, slot, A.PRIORITY_CARD)
    fill_card(slot)
  end
  -- the button
  local by = pitch_top + G.FIELD_HEIGHT * sy + A.PITCH_GAP + A.BUTTON_HEIGHT / 2
  local label = VRFW.host.command(P.C.TEXT_GET, P.BUTTON_TEXT)
  text_line(P.TEXT_BUTTON, type(label) == "string" and label or "", A.BUTTON_SCALE, cx, by, true)
  local L = P.LABEL
  P.button = {x = cx, y = by, half_w = L.PLATE_WIDTH * A.BUTTON_SCALE / 2, half_h = L.PLATE_HEIGHT * A.BUTTON_SCALE / 2}
  P.click_prev = true
  P.shown = true
end

function P.open_team_dock()
  local L = VRFW.route_board_commands.L
  if not P.shown or L.flag or L.flag2 then
    return false
  end
  funcLuaCommand(P.C.SE, P.C.SE_DECIDE)
  P.hide()
  pcall(SetupButtonGuide)
  VRFW.param.clear(P.RESULT)
  VRFW.param.set(P.RESULT, P.ITEM_TEAM_DOCK)
  funcLuaCommand(P.C.CLOSE_MENU, P.MENU)
  L.flag = true
  return true
end

local function button_clicked()
  local held = funcLuaCommand(P.C.CHECK_INPUT, P.C.MENU_CTRL, P.C.ENTER_CLICK) == true
    and funcLuaCommand(P.C.CHECK_INPUT, P.C.MENU_CTRL, P.C.ENTER) ~= true
  local pressed = held and not P.click_prev
  P.click_prev = held
  if not pressed or P.button == nil then
    return false
  end
  local mx, my = VRFW.host.menu_command(P.C.POINTER)
  if type(mx) ~= "number" or type(my) ~= "number" then
    return false
  end
  local dx, dy = 0, 0
  if (VRFW.route_board_commands ~= nil and VRFW.route_board_commands.panel_shift ~= nil) then
    dx, dy = VRFW.route_board_commands.panel_shift()
  end
  local b = P.button
  return math.abs(mx - (b.x + dx)) <= b.half_w and math.abs(my - (b.y - dy)) <= b.half_h
end

function P.follow_focus()
  local index = VRFW.host.menu_command(P.C.FOCUS_GET, P.ROWS)
  if index == P.row then
    return
  end
  P.row = index
  local team = P.read_focused_team()
  if team == nil or team.key ~= P.source then
    P.draw()
  end
end

function P.step()
  if P.pending then
    P.pending = false
    if VRFW.route_board_commands.L.flag then
      return
    end
    P.row = VRFW.host.menu_command(P.C.FOCUS_GET, P.ROWS)
    P.draw()
    return
  end
  if not P.shown then
    return
  end
  if not VRFW.route_board_commands.L.flag then
    P.follow_focus()
  end
  local dx, dy = 0, 0
  if (VRFW.route_board_commands ~= nil and VRFW.route_board_commands.panel_shift ~= nil) then
    dx, dy = VRFW.route_board_commands.panel_shift()
  end
  if P.shift == nil or P.shift[1] ~= dx or P.shift[2] ~= dy then
    P.shift = {dx, dy}
    place(P.LAYER.PITCH, 0)
    for slot = 0, P.STARTERS - 1 do
      place(P.LAYER.CARD, slot)
      place(P.LAYER.MARK, slot)
    end
    place(P.LAYER.TEXT, P.TEXT_FORMATION)
    place(P.LAYER.TEXT, P.TEXT_BUTTON)
  end
  if button_clicked() then
    P.open_team_dock()
  end
end

-- Registers the handlers on the command menu `stem`.
function P.register(stem, owns)
  if VRFW.host == nil then
    return
  end
  local id = "ChronicleDeluxe.lineup"
  VRFW.formation_card_extra = VRFW.formation_card_extra or {}
  VRFW.formation_card_extra[P.LAYER.CARD] = true
  VRFW.host.on(stem, "OnInit", {id = id, phase = "before", fn = function()
    reset()
  end})
  -- Runs once the panel is placed.
  VRFW.host.on(stem, "VRFW.route_board_commands.list_layer", {id = id, phase = "after", fn = function(r, layer, kind, rows)
    P.kind = kind
    P.on = owns(kind) and (VRFW.route_board_commands ~= nil and VRFW.route_board_commands.panel_band ~= nil) and layers_ready()
    if P.on then
      VRFW.route_board_commands.panel_band(P.BAND_ID, P.BAND_HEIGHT, P.BAND_ORDER)
      P.pending = true
    end
  end})
  -- Runs when a card instance is set up.
  VRFW.host.on(stem, "OnSetupLayer", {id = id, phase = "after", fn = function(r, a1, a2)
    if a1 == P.LAYER.CARD and type(a2) == "number" and a2 < P.STARTERS then
      name_card(a2)
    end
  end})
  -- Runs when an instance is built.
  VRFW.host.on(stem, "OnOpenLayer", {id = id, phase = "after", fn = function(r, a1, a2)
    if not P.shown or type(a2) ~= "number" then
      return
    end
    if a1 == P.LAYER.CARD and a2 < P.STARTERS then
      VRFW.host.menu_command(P.C.DRAW_PRIORITY, a1, a2, P.LAYOUT.PRIORITY_CARD, true)
      fill_card(a2)
    elseif a1 == P.LAYER.PITCH then
      VRFW.host.menu_command(P.C.DRAW_PRIORITY, a1, a2, P.LAYOUT.PRIORITY_PITCH, true)
    elseif a1 == P.LAYER.TEXT then
      VRFW.host.menu_command(P.C.DRAW_PRIORITY, a1, a2, P.LAYOUT.PRIORITY_TEXT, true)
    end
  end})
  -- Runs when another row is focused.
  VRFW.host.on(stem, "OnChangeFocus", {id = id, phase = "after", fn = function(r, a1)
    if a1 ~= P.ROWS or not P.on or P.pending or VRFW.route_board_commands.L.flag then
      return
    end
    P.follow_focus()
  end})
  VRFW.host.on(stem, "Step", {id = id, phase = "after", fn = function()
    if P.on then
      P.step()
    end
  end})
  VRFW.host.on(stem, "OnFunction", {id = id, phase = "before", fn = function(a1)
    if a1 ~= P.FUNCTION_TEAM_DOCK then
      return
    end
    if P.on then
      P.open_team_dock()
    end
    return VRFW.host.HALT
  end})
  -- Runs when the menu closes (a row decided, Back).
  VRFW.host.on(stem, "OnDecideFocus", {id = id, phase = "before", fn = function()
    P.hide()
  end})
  VRFW.host.on(stem, "OnBack", {id = id, phase = "before", fn = function()
    P.hide()
  end})
end
local K = ChronicleDeluxe.command

-- Returns the rows for kind (1 is a gate piece).
function K.rows(rows, kind)
  local s = VRFW.match_difficulty ~= nil and VRFW.match_difficulty.set(kind == 1 and "gate" or "route") or nil
  if s == nil or rows == nil then
    return rows
  end
  local keep = {}
  for i = 1, #rows do
    if s[rows[i].difficultyType] then
      keep[#keep + 1] = rows[i]
    end
  end
  return keep
end

-- Panel layout per list layer kind (0 normal, 1 gate).
K.PANEL = {
  [0] = {node = 785322415, width = 700, height = 644, slots = 8},
  [1] = {node = 3083223061, width = 700, height = 472, slots = 5}
}
K.ROW_HEIGHT = 70
K.NODE_SCALE = 2885415772         -- (layer, instance, node, width, height): a quad's size in px

function K.fit_panel(layer, kind, rows, extra)
  local p = K.PANEL[kind]
  if p == nil or rows == nil or rows < 1 then
    return
  end
  funcLuaMenuCommand(K.NODE_SCALE, layer, 0, p.node, p.width, p.height - K.ROW_HEIGHT * (p.slots - rows) + (extra or 0))
end

function K.service_piece()
  return (VRFW.route_board_commands ~= nil and VRFW.route_board_commands.service_piece ~= nil) and VRFW.route_board_commands.service_piece()
end

function K.fits_panel(kind)
  return VRFW.match_difficulty ~= nil
    and (VRFW.match_difficulty.set(kind == 1 and "gate" or "route") ~= nil or K.service_piece())
end

-- Returns whether this mod's match panel (the team lineup band) owns the panel.
function K.owns_panel(kind)
  return K.fits_panel(kind) and not K.service_piece()
end

-- Autocomplete: Select on the Chronicle row asks the board (vs_route_town_menu) to record the win.
K.SELECT_FUNCTION = 692387310     -- the CMD_FUNCTION of CMD_FUNC2 in this menu's setting (Select, keyboard Tab)
K.SELECT_INPUT = 3170216173
K.SELECT_GLYPH = 3401540579       -- the guide glyph retail pairs with CMD_FUNC2 on this menu
K.AUTOCOMPLETE_TEXT = 3847662389
K.AUTOCOMPLETE_REQUEST = 1168198373 -- read by the board
K.CHRONICLE = 1                   -- the Chronicle row's difficultyType
K.ROWS = 284009563
K.MENU = 1193383590
K.GUIDE_LAYER = 1138543975
K.CMD = {
  GET_CLEAR = 4034518619,         -- (slot, difficulty)
  GET_LOCK = 3394595467,          -- (slot, difficulty)
  FOCUSED_ROW = 2603265800,       -- (list layer) -> focused row, from 0
  GUIDE_EXTRA = 2190844859,       -- (parent menu, guide layer, 0, on): retail turns it on for a guide with two entries
  SOUND = 1917805374,
  SOUND_DECIDE = 3848881948,
  CLOSE_MENU = 320421347,
}

-- Returns the focused battle row.
function K.focused_row()
  return VRFW.route_board_commands.L.t3[VRFW.host.menu_command(K.CMD.FOCUSED_ROW, K.ROWS) + 1]
end

-- Returns whether a row is an open, not yet beaten Chronicle battle.
function K.can_autocomplete(row)
  if row == nil or row.difficultyType ~= K.CHRONICLE or K.service_piece() then
    return false
  end
  local slot = VRFW.route_board_commands.L.n2
  return not funcLuaCommand(K.CMD.GET_LOCK, slot, K.CHRONICLE) and not funcLuaCommand(K.CMD.GET_CLEAR, slot, K.CHRONICLE)
end

-- Closes the menu with the board's request written (no retail result: the board goes back as after Back).
function K.request_autocomplete()
  local L = VRFW.route_board_commands.L
  funcLuaCommand(K.CMD.SOUND, K.CMD.SOUND_DECIDE)
  ChronicleDeluxe.lineup.hide()
  SetupButtonGuide()
  VRFW.param.replace(K.AUTOCOMPLETE_REQUEST, 1)
  funcLuaCommand(K.CMD.CLOSE_MENU, K.MENU)
  L.flag = true
end

if VRFW.host ~= nil then
  VRFW.host.on("vs_route_town_command_select_menu", "VRFW.route_board_commands.rows", {id = "ChronicleDeluxe.board", phase = "around",
    fn = function(nxt, rows, kind, slot)
      return nxt(K.rows(rows, kind), kind, slot)
    end})
  VRFW.host.on("vs_route_town_command_select_menu", "VRFW.route_board_commands.list_layer", {id = "ChronicleDeluxe.panel_fit",
    phase = "after", fn = function(r, layer, kind, rows)
      if K.fits_panel(kind) then
        K.fit_panel(layer, kind, rows, VRFW.route_board_commands ~= nil and VRFW.route_board_commands.panel.extra or 0)
      end
    end})
  VRFW.host.on("vs_route_town_command_select_menu", "VRFW.route_board_commands.panel_extra", {id = "ChronicleDeluxe.panel_band",
    phase = "after", fn = function(r, layer, kind, rows, extra)
      if layer ~= nil and K.fits_panel(kind) then
        K.fit_panel(layer, kind, rows, extra)
      end
    end})
  VRFW.host.on("vs_route_town_command_select_menu", "VRFW.route_board_commands.guide", {id = "ChronicleDeluxe.autocomplete",
    phase = "after", fn = function(r, item, icons, texts, commands)
      if K.can_autocomplete(item) then
        icons[#icons + 1], texts[#texts + 1], commands[#commands + 1] = K.SELECT_GLYPH, K.AUTOCOMPLETE_TEXT, K.SELECT_INPUT
        VRFW.host.menu_command(K.CMD.GUIDE_EXTRA, VRFW.route_board_commands.L.n12, K.GUIDE_LAYER, 0, true)
      end
    end})
  VRFW.host.on("vs_route_town_command_select_menu", "OnFunction", {id = "ChronicleDeluxe.autocomplete",
    phase = "before", fn = function(a1)
      local L = VRFW.route_board_commands.L
      if a1 ~= K.SELECT_FUNCTION or L.flag or L.flag2 or not K.can_autocomplete(K.focused_row()) then
        return
      end
      K.request_autocomplete()
      return VRFW.host.HALT
    end})
  ChronicleDeluxe.lineup.register("vs_route_town_command_select_menu", K.owns_panel)
end
